class Menu {
  private items: string[] = [];
  add(item: string) { this.items.push(item); }
  createIterator() { return new MenuIterator(this.items); }
}

class MenuIterator {
  private index = 0;
  constructor(private items: string[]) {}
  hasNext() { return this.index < this.items.length; }
  next() { return this.items[this.index++]; }
}

class NumberCollection {
  private numbers: number[] = [];
  add(n: number) { this.numbers.push(n); }
  // Traversal state is stored on the collection itself
  private cursor = 0;
  hasNext() { return this.cursor < this.numbers.length; }
  next() { return this.numbers[this.cursor++]; }
}

// Version A: iterator objects returned by the collection
class ListA {
  private items: number[] = [];
  add(i: number) { this.items.push(i); }
  iterator() { return new ListAIterator(this.items); }
}
class ListAIterator {
  private index = 0;
  constructor(private items: number[]) {}
  hasNext() { return this.index < this.items.length; }
  next() { return this.items[this.index++]; }
}

// Version B: traversal state stored on the collection instance
class ListB {
  private items: number[] = [];
  private cursor = 0;
  add(i: number) { this.items.push(i); }
  hasNext() { return this.cursor < this.items.length; }
  next() { return this.items[this.cursor++]; }
}
